const crypto = require('crypto');
const MAX_SKEW_SECONDS = 300;
const item = $input.first();
const headers = item.json.headers || {};
const secret = $env.LENDLOOP_WEBHOOK_SECRET;

// Prefer the exact raw bytes; fall back to re-serialising the parsed body.
let rawBody;
const bin = item.binary && item.binary.data;
if (bin && bin.data && bin.data !== 'filesystem-v2' && bin.data !== 'filesystem') {
  rawBody = Buffer.from(bin.data, 'base64').toString('utf8');
} else if (bin) {
  rawBody = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} else {
  rawBody = JSON.stringify(item.json.body);
}

function reject(reason) {
  console.warn(`Rejected LendLoop webhook: ${reason}`);
  return [{ json: { valid: false, reason } }];
}

if (!secret) return reject('LENDLOOP_WEBHOOK_SECRET not configured');
const signature = String(headers['x-lendloop-signature'] || '');
const timestamp = String(headers['x-lendloop-timestamp'] || '');
if (!/^[0-9a-f]{64}$/i.test(signature) || !/^\d{1,12}$/.test(timestamp)) return reject('missing or malformed signature headers');

const now = Math.floor(Date.now() / 1000);
if (Math.abs(now - Number(timestamp)) > MAX_SKEW_SECONDS) return reject('timestamp outside allowed window');

const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest();
const given = Buffer.from(signature, 'hex');
if (given.length !== expected.length || !crypto.timingSafeEqual(given, expected)) return reject('bad signature');

let payload;
try { payload = JSON.parse(rawBody); } catch { return reject('invalid JSON'); }
return [{ json: { valid: true, payload } }];

const p = $input.first().json.payload;
const dates = p.startDate === p.endDate ? p.startDate : `${p.startDate} to ${p.endDate}`;
const hi = p.recipient.firstName ? `Hi ${p.recipient.firstName},` : 'Hi,';
const lines = {
  'loan.requested': [`New borrow request: ${p.toolName}`, `A neighbor would like to borrow your ${p.toolName} (${dates}). Open LendLoop → Incoming to approve or decline.`],
  'loan.approved': [`Approved: ${p.toolName}`, `Good news — your request to borrow ${p.toolName} (${dates}) was approved. Please return it by ${p.endDate}.`],
  'loan.declined': [`Request declined: ${p.toolName}`, `Your request to borrow ${p.toolName} (${dates}) was declined. Have a look for another option on LendLoop.`],
  'loan.cancelled': [`Request cancelled: ${p.toolName}`, `The request to borrow your ${p.toolName} (${dates}) was cancelled by the borrower.`],
  'loan.returned': [`Returned: ${p.toolName}`, `The owner marked ${p.toolName} as returned. Thanks for borrowing responsibly!`],
};
const [subject, body] = lines[p.event] || [`LendLoop update: ${p.toolName}`, `Status: ${p.status}`];
return [{ json: {
  to: p.recipient.email,
  subject,
  text: `${hi}\n\n${body}\n\n— LendLoop`,
  loanId: p.loanId,
  idempotencyKey: p.deliveryKey,
  event: p.event,
} }];

// Mock transport: log without the full address.
const [user, domain] = String($json.to).split('@');
console.log(`[mock email] to ${user.slice(0, 2)}***@${domain} :: ${$json.subject}`);
return { json: { mocked: true } };

const crypto = require('crypto');
const msg = $('Compose message').first().json;
const rawBody = JSON.stringify({ loanId: msg.loanId, type: 'request_notification', idempotencyKey: msg.idempotencyKey, status: 'sent' });
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = crypto.createHmac('sha256', $env.LENDLOOP_WEBHOOK_SECRET).update(`${timestamp}.${rawBody}`).digest('hex');
return { json: { rawBody, timestamp, signature, outcome: 'sent' } };

const crypto = require('crypto');
const msg = $('Compose message').first().json;
const error = String(($json.error && ($json.error.message || $json.error)) || 'send failed').slice(0, 300);
const rawBody = JSON.stringify({ loanId: msg.loanId, type: 'request_notification', idempotencyKey: msg.idempotencyKey, status: 'failed', error });
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = crypto.createHmac('sha256', $env.LENDLOOP_WEBHOOK_SECRET).update(`${timestamp}.${rawBody}`).digest('hex');
return { json: { rawBody, timestamp, signature, outcome: 'failed' } };
